CREATE TABLE IF NOT EXISTS forum_posts (id INTEGER PRIMARY KEY AUTOINCREMENT, fete TEXT NOT NULL DEFAULT '', parent_id INTEGER NULL, lang TEXT NOT NULL DEFAULT 'fr', name TEXT NOT NULL, email TEXT NOT NULL, subject TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', is_team INTEGER NOT NULL DEFAULT 0, ip_hash TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contact_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, email TEXT, subject TEXT, body TEXT, lang TEXT, ip_hash TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS rate_log (id INTEGER PRIMARY KEY AUTOINCREMENT, ip_hash TEXT, action TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS agent_actions (action_id TEXT PRIMARY KEY, applied_at TEXT, result TEXT);
